-- 012_legal_pages_india.sql
--
-- Rewrites the Privacy Policy and Terms of Service, and adds a Refund Policy.
--
-- WHY THE EXISTING PAGES WERE WRONG, NOT JUST THIN
--
-- `009_seed_legal_pages.sql` wrote a privacy policy built on UK/EU GDPR: it named
-- the Information Commissioner's Office as the supervisory authority and cited
-- Standard Contractual Clauses for transfers. The product it describes charges in
-- rupees and paise and settles over UPI. Naming a regulator with no jurisdiction
-- over the operator is worse than naming none — it tells a user to complain to a
-- body that will not hear them. These pages are therefore rewritten against
-- India's Digital Personal Data Protection Act, 2023, the Information Technology
-- Act, 2000 and the Consumer Protection (E-Commerce) Rules, 2020.
--
-- WHAT THE REFUND POLICY IS ALLOWED TO SAY
--
-- Every rule in the refund policy is taken from the code that actually moves the
-- money, not from what would read well:
--
--   • `REFUND_FEE_ON` in src/lib/bookings/actions.ts — the platform fee returns on
--     `declined`, `expired` and `cancelled_shop`, and deliberately NOT on
--     `cancelled_customer`.
--   • There is no customer-facing withdrawal anywhere in src/ — `withdraw-dialog`
--     is under dashboard/expert and pays a shop. So wallet balance is credit, and
--     the policy says so instead of implying a bank refund.
--   • The enrollment fee returns only when a listing is rejected
--     (`enrollment_refunded_at`).
--   • `subscribeToPlan` treats the free tier as a cancellation and does not
--     pro-rate, so the policy does not promise pro-rata.
--
-- A refund policy that describes a path the software does not have is not a
-- policy, it is a liability. If any of those rules change, this file changes with
-- them.
--
-- PLACEHOLDERS
--
-- `<mark>[FILL IN — …]</mark>` marks every fact that cannot be derived from the
-- codebase: the registered entity name, the registered address, the grievance
-- officer, and the seat of jurisdiction. `mark` renders as a highlight, so an
-- unreplaced placeholder is glaring on the published page rather than hidden in
-- a wall of text. The Consumer Protection (E-Commerce) Rules require the entity
-- and grievance-officer disclosures by name; leaving them blank is a compliance
-- gap, so they are made impossible to miss.
--
-- This migration is an upsert and is safe to re-run: it updates the three pages
-- where they exist and inserts them where they do not. `seo_pages` has only a
-- primary key on `id` — there is no unique index on (slug, path_prefix) — so
-- `on conflict` is unavailable and the update-then-insert CTE below is the
-- correct shape rather than a stylistic choice.

with payload (slug, title, meta_title, meta_description, keywords, sections) as (
  values
  -- ── Privacy Policy ─────────────────────────────────────────────────────────
  (
    'privacy',
    'Privacy Policy',
    -- No " — FixGrid" suffix. The root layout's metadata template is
    -- `%s · FixGrid`, so a brand in `meta_title` renders as
    -- "Privacy Policy — FixGrid · FixGrid".
    'Privacy Policy',
    'What personal data FixGrid collects, why we collect it, how long we keep it, and the rights you have over it under India''s DPDP Act 2023.',
    array['privacy policy','DPDP Act','data protection','personal data','FixGrid'],
    $json$[
      {
        "type": "compact_hero",
        "eyebrow": "Legal",
        "heading": "Privacy Policy",
        "subtitle": "What we collect, why we collect it, and what you can do about it. Last updated 16 August 2026."
      },
      { "type": "table_of_contents", "title": "On this page" },
      {
        "type": "rich_text",
        "width": "prose",
        "html": "<p>This policy is written to be read. If any part of it is unclear, write to us and we will explain it in plainer words — that is a better outcome for both of us than you agreeing to something you did not follow.</p><h2>Who we are</h2><p>FixGrid is a directory and booking platform for local repair shops, operated at <strong>vytron.me</strong> by <mark>[FILL IN — registered legal entity name]</mark>, with its registered office at <mark>[FILL IN — registered office address]</mark>.</p><p>Under the <strong>Digital Personal Data Protection Act, 2023</strong> (the <em>DPDP Act</em>), we are the <strong>Data Fiduciary</strong> for the personal data described here, and you are the <strong>Data Principal</strong>. In plain terms: you own this data, we are answerable for what we do with it.</p><h2>What we collect</h2><h3>Information you give us</h3><ul><li><strong>Account</strong> — your email address and a password. The password is hashed by our authentication provider before it is stored; we never see it or hold it in readable form.</li><li><strong>Profile</strong> — your display name, and optionally your full name, phone number, timezone and preferred contact method.</li><li><strong>Addresses</strong> — any service address you save for a home visit or a pickup.</li><li><strong>Repair requests</strong> — what broke, the shop you chose, the slot you picked, and any photos or files you attach.</li><li><strong>Messages</strong> — what you send a shop through FixGrid, including attachments.</li><li><strong>Disputes</strong> — the reason you raise, the outcome you ask for, evidence you upload, and the messages exchanged.</li><li><strong>Reviews</strong> — your rating and review text, published alongside your display name.</li><li><strong>Shop listing</strong> (shop owners) — shop name, address, contact details, opening hours, services, prices, inventory, photos and the warranty you offer.</li><li><strong>Verification evidence</strong> (shop owners) — the documents and photographs you submit to claim or verify a shop, and any bill you upload against a completed job.</li></ul><h3>Information produced by using FixGrid</h3><ul><li><strong>Wallet and ledger records</strong> — every top-up, fee, refund, rebate and payout, with amounts and timestamps. These are financial records and are retained accordingly.</li><li><strong>Booking history</strong> — each status change and who made it.</li><li><strong>Server logs</strong> — IP address, browser type, the pages requested and when.</li><li><strong>One session cookie</strong>, set by our authentication provider, so you stay signed in. We set no advertising cookies and no cross-site tracking cookies.</li></ul><h2>A note about payments</h2><p><mark>[FILL IN — delete this section once live payment processing is enabled]</mark></p><p>FixGrid does not currently process real payments. The wallet top-up, the UPI screens and the card fields on this site are a <strong>simulation used for testing</strong>: no money moves, no bank is contacted, and <strong>no card number, UPI PIN, CVV or bank credential is stored anywhere</strong>. Please do not enter a real UPI PIN or a real card number on FixGrid. When real payment processing is enabled, this section will be replaced with the name of the payment processor and a description of what it receives.</p><h2>Why we use your data</h2><p>We use it to create and run your account; to show a shop listing to prospective customers; to pass a repair request and the contact details you chose to share to the shop you selected; to operate your wallet and keep an auditable record of every rupee; to send transactional email such as booking confirmations and password resets; to investigate abuse and enforce our Terms; and to keep the service secure.</p><p>Our lawful basis is your <strong>consent</strong> for the purposes described when you give us the data, and the <strong>legitimate uses</strong> permitted by section 7 of the DPDP Act — principally the purpose for which you voluntarily provided the data, and compliance with law. Marketing email is sent only if you opt in, and you can withdraw that at any time from your notification settings.</p><h2>Who we share it with</h2><p><strong>We do not sell your personal data.</strong> We share it only in these situations:</p><ul><li><strong>With the shop you book</strong> — a shop sees your display name, the contact details you chose to share, your repair description, your attachments and the service address if the job needs one. It sees this because it cannot do the job otherwise.</li><li><strong>With our infrastructure providers</strong>, acting as Data Processors on our instructions: <strong>Supabase</strong> (database, authentication and file storage) and <strong>Vercel</strong> (application hosting).</li><li><strong>Publicly</strong> — your display name and review text, if you post a review. Consider that permanent.</li><li><strong>When the law requires it</strong> — a court order, a lawful demand from an authority, or where disclosure is necessary to investigate fraud or a threat to someone's safety.</li></ul><h2>Where your data is stored</h2><p>Our infrastructure providers are companies established outside India, and your data may be stored or processed outside India on their systems. The DPDP Act permits such transfers except to territories the Central Government has restricted; we do not transfer data to any restricted territory.</p><h2>How long we keep it</h2><ul><li><strong>Account and profile data</strong> — while your account is open.</li><li><strong>Server logs</strong> — 30 days.</li><li><strong>Bookings, messages, disputes and ledger entries</strong> — retained after account closure where we need them to evidence a completed transaction, honour a warranty, or meet a legal or tax obligation. We keep the record, not a live profile.</li></ul><p>When you ask us to delete your account we erase your personal data within 30 days, except where a specific law requires us to keep a particular record for longer. Where that applies we will tell you which record and why.</p><h2>Your rights</h2><p>As a Data Principal under the DPDP Act you may:</p><ul><li><strong>Access</strong> a summary of the personal data we hold about you and what we have done with it (section 11).</li><li><strong>Correct or complete</strong> inaccurate data, and <strong>erase</strong> data we no longer need for the purpose you gave it for (section 12).</li><li><strong>Nominate</strong> another person to exercise your rights if you die or become incapacitated (section 14).</li><li><strong>Withdraw consent</strong> at any time. Withdrawal is not retrospective — it stops future processing, it does not undo what was lawfully done before.</li><li><strong>Complain</strong> to us first, and then to the Data Protection Board of India if we do not resolve it.</li></ul><p>To exercise any of these, email <strong>hello@vytron.me</strong> from the address on your account.</p><h2>Grievance redressal</h2><p>Our Grievance Officer, appointed under the Consumer Protection (E-Commerce) Rules, 2020 and the Information Technology Rules, 2021, is:</p><p><mark>[FILL IN — grievance officer name]</mark><br><mark>[FILL IN — designation]</mark><br>Email: <strong>hello@vytron.me</strong><br>Address: <mark>[FILL IN — address for grievances]</mark></p><p>We acknowledge a grievance within <strong>48 hours</strong> and aim to resolve it within <strong>30 days</strong>. Complaints about unlawful content are handled on the shorter timelines the IT Rules require.</p><h2>Security</h2><p>All traffic is served over HTTPS. Passwords are hashed by our authentication provider. Access to your rows in our database is enforced at the database itself by row-level security policies, so a bug in the application is not by itself enough to expose another person's data. Files you upload are held in private storage and served through our own access-checked routes, not by public link.</p><p>No system is perfectly secure. If we become aware of a personal data breach affecting you, we will notify you and the Data Protection Board as the DPDP Act requires.</p><h2>Children</h2><p>FixGrid is not intended for anyone under 18. We do not knowingly collect the personal data of a child without verifiable consent from a parent or guardian, and we do not undertake tracking, behavioural monitoring or targeted advertising directed at children. If you believe a child has created an account, tell us and we will remove it.</p><h2>Cookies</h2><p>We use one essential cookie, issued by our authentication provider, to keep you signed in. It is required for the site to work and cannot be switched off while you are logged in. We do not use analytics, advertising or cross-site tracking cookies, so there is no consent banner to click through.</p><h2>Changes to this policy</h2><p>When our practices change we will update this page and the revision date at the top. If a change materially reduces your rights we will tell account holders by email rather than relying on you to notice.</p><h2>Contact</h2><p>Questions about this policy, or about the data we hold: <strong>hello@vytron.me</strong>.</p>"
      }
    ]$json$::jsonb
  ),

  -- ── Terms of Service ───────────────────────────────────────────────────────
  (
    'terms',
    'Terms of Service',
    'Terms of Service',
    'The terms on which you use FixGrid: what we do, what the repair shop does, who is responsible for the work, and the limits of our liability.',
    array['terms of service','terms and conditions','marketplace terms','FixGrid'],
    $json$[
      {
        "type": "compact_hero",
        "eyebrow": "Legal",
        "heading": "Terms of Service",
        "subtitle": "FixGrid connects you with independent repair shops. The shop does the work and stands behind it. Last updated 16 August 2026."
      },
      { "type": "table_of_contents", "title": "On this page" },
      {
        "type": "rich_text",
        "width": "prose",
        "html": "<h2>The short version</h2><p>FixGrid is a marketplace. We help you find a repair shop, book it and pay a booking fee. <strong>The shop is the one repairing your device, setting its price and giving you a warranty — not us.</strong> If the repair goes wrong, your claim is against the shop. We will help where we hold money or evidence, but we are not the repairer and we do not guarantee the work.</p><p>The sections below say the same thing carefully. They matter, so please read them.</p><h2>Agreement to these terms</h2><p>By creating an account or using FixGrid you agree to these terms. If you do not agree, do not use the service. These terms are between you and <mark>[FILL IN — registered legal entity name]</mark> (<em>FixGrid</em>, <em>we</em>, <em>us</em>), which operates <strong>vytron.me</strong>.</p><h2>What FixGrid is, and what it is not</h2><p>FixGrid is an <strong>intermediary</strong>. We publish listings for independent repair businesses, let you compare them, take a booking, and move the fees described below.</p><p>We are <strong>not</strong>:</p><ul><li>a repair business, and we do not perform, supervise or inspect any repair;</li><li>the employer, agent, partner or franchisor of any shop listed here;</li><li>the seller of any part fitted or any device serviced;</li><li>a guarantor of any shop's work, honesty, pricing, licensing, insurance or availability.</li></ul><p>Every shop on FixGrid is an independent third party that decides for itself what to charge, whether to accept your job, how to do it and what warranty to give. Listings, ratings, verification marks and warranty labels are information reported to us or computed from our records. They are offered in good faith, and they are not a recommendation, an endorsement or a promise about what will happen in your particular case.</p><h2>Who may use FixGrid</h2><p>You must be at least 18 and capable of entering a binding contract. If you use FixGrid for a business, you confirm you are authorised to bind that business.</p><h2>Your account</h2><p>Keep your credentials to yourself; you are responsible for what happens under your account. Give us accurate information and keep it current. Tell us promptly if you think your account has been compromised. Do not create an account for someone else without their authority, and do not run multiple accounts to evade a suspension or to manipulate ratings.</p><h2>Booking a repair: your contract is with the shop</h2><p>When you request a booking and a shop accepts it, <strong>a contract for the repair forms between you and that shop.</strong> FixGrid is not a party to it. That contract governs the scope of the work, the price quoted, the parts used, the timescale and the warranty.</p><p>You are responsible for describing the fault honestly, for backing up your own data before handing over a device, for removing anything you do not want a stranger to see, and for being available at the slot you chose. The shop is responsible for the work.</p><p><strong>Back up your data.</strong> Repairs can and do result in data loss, including where nobody was careless. Neither FixGrid nor, in many cases, the shop can recover it. Do not hand over the only copy of something you cannot lose.</p><h2>Money: what we charge, and what we hold</h2><p>Full detail is in our <a href=\"/refunds\">Refund Policy</a>, which forms part of these terms. In summary:</p><ul><li><strong>Platform booking fee</strong> — a fee we charge <em>you</em>, the customer, when you request a booking. It is ours, for running the platform. It is not part of the repair price and the shop does not receive it.</li><li><strong>The repair price</strong> — quoted by the shop and owed to the shop.</li><li><strong>Wallet</strong> — you may hold a balance on FixGrid to pay booking fees and subscription charges. Wallet balance is <strong>platform credit</strong>: it is spendable on FixGrid and is not withdrawable to a bank account.</li><li><strong>Shop listing fee and subscriptions</strong> — charges to shops for a listing, and optional plans for customers.</li><li><strong>Shop rebate</strong> — a percentage we may credit a shop against an approved bill. It is a platform incentive, not a payment from you.</li></ul><p>We keep a double-entry ledger of every movement. You can see your own entries in your dashboard, and we will explain any entry you ask about.</p><h2>Warranty is the shop's promise</h2><p>Where a shop advertises a warranty, <strong>that warranty is given by the shop and is enforceable against the shop.</strong> We display its length because it helps you choose. We do not underwrite it, insure it, or undertake to perform it if the shop will not or cannot — for example if it closes down.</p><h2>Disputes between customers and shops</h2><p>A disagreement about a repair — quality, delay, price, damage, a warranty claim — is <strong>between you and the shop</strong>, and you should raise it with the shop first. FixGrid is not a party to that dispute, is not an arbitrator, and does not decide the rights and wrongs of the underlying work.</p><p>We do provide a dispute form, because we hold two things that can help: the fees we collected, and the record of what happened. Where a dispute is raised we may, <strong>entirely at our discretion</strong>, review our own records, ask both sides for information, and return or withhold <strong>money we ourselves hold</strong> — such as your platform booking fee, or a rebate not yet paid.</p><p>Two limits on that, stated plainly:</p><ul><li><strong>We cannot move the shop's money.</strong> The repair price is the shop's. We have no power to claw it back and we do not undertake to reimburse it.</li><li><strong>Nothing we do in that process is an adjudication</strong>, an admission, or an assumption of liability for the repair. Declining to intervene is not a finding against you, and intervening once does not oblige us to intervene again.</li></ul><p>Your legal remedies against the shop are unaffected by any of this, and nothing here requires you to use our process before pursuing them.</p><h2>Listing a shop</h2><p>If you list a shop you additionally agree that: you are authorised to represent it; every claim you publish — services, prices, hours, credentials, warranty — is accurate and kept current; you hold the licences, registrations, insurance and tax registrations your trade and turnover require; you will honour quotes you give and warranties you advertise; you will not solicit customers off-platform to avoid fees; and any bill you submit reflects work you actually did at a price you actually charged.</p><p>You are the service provider of record for every job you accept, and you are responsible for it. You agree to deal with your customers' complaints directly and in good faith. We may suspend or remove a listing that misrepresents itself, that attracts substantiated complaints, or that submits a bill we find to be inflated or fabricated.</p><h2>Reviews and the content you post</h2><p>Review only work that actually happened, and describe it truthfully. Do not post another person's private information, anything unlawful, or anything you do not have the right to publish. Do not write, buy or solicit fake reviews — for your own shop or against a competitor.</p><p>You keep ownership of what you post. You grant us a non-exclusive, royalty-free, worldwide licence to host, display and distribute it on FixGrid and in marketing for FixGrid. We may remove content that breaches these terms or the law, and we may act on a takedown request as the IT Rules require. We do not edit a review to change its meaning.</p><h2>Things you must not do</h2><p>Do not use FixGrid to break the law; scrape it in bulk or resell our listings; probe, overload or interfere with the service or its security; misrepresent who you are; manipulate ratings or search results; harass another user or a shop; or use it to launder money or take payment for something you do not intend to deliver.</p><h2>Suspension and termination</h2><p>You may close your account at any time. We may suspend or terminate an account, with notice where practical and immediately where necessary, if it breaches these terms, presents a risk of fraud or harm, or if we are required to. Termination does not cancel money already properly owed in either direction, and the ledger record survives it.</p><h2>Limitation of liability</h2><p>This section limits what we owe you. Read it.</p><p><strong>To the fullest extent the law allows, FixGrid is not liable for the acts or omissions of any repair shop</strong> — including defective or incomplete work, damage to or loss of a device, loss of data, delay, non-attendance, overcharging, a refused warranty claim, injury or property damage arising from a repair, or a shop ceasing to trade.</p><p>We are not liable for indirect, incidental, special, punitive or consequential loss, nor for loss of profit, revenue, goodwill, business opportunity, or data, however caused.</p><p><strong>Where we are liable, our total liability to you for all claims connected with a booking is limited to the fees FixGrid actually collected from you in respect of that booking.</strong> For a claim not connected with a particular booking, it is limited to the fees you paid us in the three months before the claim arose.</p><p>Two things this section does <strong>not</strong> do. It does not exclude liability for death or personal injury caused by our own negligence, for our own fraud or fraudulent misrepresentation, or for anything else that cannot lawfully be excluded. And it does not displace the rights the <strong>Consumer Protection Act, 2019</strong> gives you as a consumer — those rights stand whatever this page says, and any term here that a court finds unfair within the meaning of that Act simply falls away without affecting the rest.</p><h2>Indemnity</h2><p>You agree to indemnify FixGrid against claims, losses and reasonable legal costs arising from your breach of these terms, from content you post, from your infringement of someone else's rights, and — if you are a shop — from the repairs you carry out.</p><h2>Our status as an intermediary</h2><p>FixGrid is an intermediary within the meaning of the <strong>Information Technology Act, 2000</strong>, and relies on the protection of section 79 of that Act for information published by its users. We do not author shop listings or reviews and we do not verify every claim in them before publication. We act on valid notices of unlawful content within the timelines the Information Technology Rules, 2021 prescribe, and we publish grievance contact details as those rules and the Consumer Protection (E-Commerce) Rules, 2020 require.</p><h2>Grievance officer</h2><p><mark>[FILL IN — grievance officer name]</mark><br><mark>[FILL IN — designation]</mark><br>Email: <strong>hello@vytron.me</strong><br>Address: <mark>[FILL IN — address for grievances]</mark></p><p>Acknowledged within 48 hours; resolved within 30 days.</p><h2>Changes</h2><p>We may change the service and these terms. Material changes will be posted here with a new revision date, and account holders will be told by email. Continuing to use FixGrid after a change means you accept the revised terms; if you do not, close your account.</p><h2>Governing law and jurisdiction</h2><p>These terms are governed by the laws of <strong>India</strong>. The courts at <mark>[FILL IN — city, e.g. New Delhi]</mark> have exclusive jurisdiction, save that nothing in this clause prevents a consumer from approaching a consumer forum available to them under the Consumer Protection Act, 2019.</p><h2>Contact</h2><p><strong>hello@vytron.me</strong></p>"
      }
    ]$json$::jsonb
  ),

  -- ── Refund Policy ──────────────────────────────────────────────────────────
  (
    'refunds',
    'Refund Policy',
    'Refund Policy',
    'Exactly which FixGrid payments are refundable and which are not: the platform booking fee, wallet top-ups, the shop listing fee, subscriptions and the repair price itself.',
    array['refund policy','cancellation','booking fee refund','wallet credit','FixGrid'],
    $json$[
      {
        "type": "compact_hero",
        "eyebrow": "Legal",
        "heading": "Refund Policy",
        "subtitle": "Which payments come back, which do not, and how long it takes. Last updated 16 August 2026."
      },
      { "type": "table_of_contents", "title": "On this page" },
      {
        "type": "rich_text",
        "width": "prose",
        "html": "<p>This policy forms part of our <a href=\"/terms\">Terms of Service</a>. It describes what the platform actually does, not what we would like it to do — where a refund is automatic we say so, and where there is no refund we say that too rather than leaving you to find out.</p><h2>The one distinction that matters</h2><p>Two separate payments happen when you book a repair, and only one of them is ours:</p><ul><li>The <strong>platform booking fee</strong> is paid to <strong>FixGrid</strong>, for running the platform. This policy governs it.</li><li>The <strong>repair price</strong> is paid to <strong>the shop</strong>, for the work. It is the shop's money and the shop's policy governs it. We cannot refund it, because we never held it.</li></ul><p>If you want the repair price back, that is a claim against the shop. See <a href=\"/terms\">Disputes</a> for what we can and cannot do to help.</p><h2>At a glance</h2><table><caption>What is refundable on FixGrid</caption><thead><tr><th scope=\"col\">Payment</th><th scope=\"col\">Refundable?</th><th scope=\"col\">Returned as</th></tr></thead><tbody><tr><th scope=\"row\">Booking fee — shop declined, request expired, or shop cancelled</th><td>Yes, automatically</td><td>Wallet credit</td></tr><tr><th scope=\"row\">Booking fee — you cancelled your own request</th><td>No</td><td>—</td></tr><tr><th scope=\"row\">The repair price</th><td>Not by us</td><td>Shop's own policy</td></tr><tr><th scope=\"row\">Wallet top-up</th><td>No</td><td>Stays as credit</td></tr><tr><th scope=\"row\">Shop listing fee — listing rejected</th><td>Yes, in full</td><td>Wallet credit</td></tr><tr><th scope=\"row\">Shop listing fee — listing approved</th><td>No</td><td>—</td></tr><tr><th scope=\"row\">Subscription plan</th><td>No pro-rata refund</td><td>—</td></tr></tbody></table><h2>The platform booking fee</h2><p>You pay this the moment you request a booking, before any shop has agreed to anything. We return it in full, automatically, when the repair is not going to happen for a reason that was not your doing:</p><ul><li>the <strong>shop declines</strong> your request;</li><li>the request <strong>expires</strong> because nobody answered it in time;</li><li>the <strong>shop cancels</strong> after accepting.</li></ul><p>In each of those cases you paid us for a repair you are not getting, which is a charge for nothing. The credit appears in your wallet within minutes and is listed in your wallet history. You do not need to ask.</p><h3>If you cancel your own request</h3><p><strong>The booking fee is not refunded when you cancel.</strong> Our reasoning is that the fee has by then bought what it was for: the shop was engaged and a slot was held against other customers.</p><p>We would rather state that clearly than bury it. If you cancelled within moments of requesting, or before any shop had responded at all, write to us — that situation is closer to a charge for nothing than to a cancellation, and we would sooner look at it than defend a technicality.</p><h2>The repair price</h2><p>Paid to the shop, governed by the shop. Ask the shop for its cancellation and refund terms before you hand over your device — and if it advertises a warranty on FixGrid, that warranty is a promise the shop made and you can hold it to.</p><p>FixGrid does not refund the repair price, does not hold it in escrow on your behalf, and does not undertake to reimburse you if a shop refuses a refund it should have given.</p><h2>Wallet top-ups</h2><p><strong>Money you add to your FixGrid wallet is platform credit and is not refundable.</strong> It can be spent on FixGrid — booking fees, subscription charges — and it cannot be withdrawn to a bank account, card or UPI ID. There is no withdrawal facility for customer wallets.</p><p>So only top up what you expect to spend here. Credit does not expire, and any unspent balance stays available while your account is open.</p><p><mark>[FILL IN — revisit this section before enabling live payments]</mark> While payments on FixGrid are simulated, no real money reaches us and there is nothing to refund. Once real payment processing is enabled, this section will be revisited, including any requirement that applies to holding customer balances.</p><h2>Shop listing fee</h2><p>A shop pays a one-time fee to be listed. It is <strong>refunded in full</strong>, as wallet credit, if we reject the listing — we do not keep money for a listing we declined to publish. It is <strong>not refunded</strong> once the listing is approved and published, whether or not the shop goes on to receive bookings, and it is not refunded if we later suspend a listing for breaching our terms.</p><h2>Subscription plans</h2><p>Paid plans are charged for the period in advance. You can move to the free tier at any time, which stops future charges and leaves your current period running to its end. <strong>There is no pro-rata refund</strong> for the part of a period you do not use, and included booking allowances do not carry over.</p><p>If a plan charge was taken twice, or taken after you moved to the free tier, that is our error — tell us and we will correct it.</p><h2>The shop rebate</h2><p>For completeness, since it appears in shop ledgers: when a shop submits a bill for a completed job and we approve it, we credit the shop a percentage of that bill. That is a platform incentive paid out of our own fees, capped at the value of the job. It is not a refund, it is not paid by you, and it does not reduce anything you are owed.</p><h2>How refunds are paid</h2><p>Every refund under this policy is paid as <strong>credit to your FixGrid wallet</strong>, not back to a card, bank account or UPI ID. Each one appears as its own line in your wallet history, with the amount, the reason and the booking it relates to, so you can check our arithmetic.</p><h2>Timelines</h2><ul><li><strong>Automatic refunds</strong> (shop declined, request expired, shop cancelled) — within minutes of the status change.</li><li><strong>Listing fee refunds</strong> — when the listing is rejected.</li><li><strong>Anything you have to ask for</strong> — acknowledged within 48 hours, decided within 30 days, usually much sooner.</li></ul><p>If an automatic refund does not appear, it is a fault on our side. Tell us the booking reference and we will trace it in the ledger and correct it.</p><h2>Your statutory rights</h2><p>Nothing in this policy takes away the rights you have as a consumer under the <strong>Consumer Protection Act, 2019</strong>, or your right to approach a consumer forum. Where anything here conflicts with a right you cannot contract out of, that right wins.</p><h2>How to ask for a refund</h2><p>Email <strong>hello@vytron.me</strong> with your <strong>booking reference</strong> and what you are asking for. If you are not satisfied with the answer, escalate to our Grievance Officer:</p><p><mark>[FILL IN — grievance officer name]</mark><br><mark>[FILL IN — designation]</mark><br>Email: <strong>hello@vytron.me</strong><br>Address: <mark>[FILL IN — address for grievances]</mark></p>"
      }
    ]$json$::jsonb
  )
),

updated as (
  update public.seo_pages p
     set title            = d.title,
         meta_title       = d.meta_title,
         meta_description = d.meta_description,
         keywords         = d.keywords,
         content_sections = d.sections,
         status           = 'published',
         is_indexed       = true,
         is_followed      = true,
         schema_type      = 'WebPage',
         published_at     = coalesce(p.published_at, now()),
         updated_at       = now()
    from payload d
   where p.slug = d.slug
     and coalesce(p.path_prefix, '') = ''
  returning p.slug
)

insert into public.seo_pages (
  slug, path_prefix, title, status, is_indexed, is_followed,
  schema_type, meta_title, meta_description, keywords,
  published_at, content_sections
)
select
  d.slug, '', d.title, 'published', true, true,
  'WebPage', d.meta_title, d.meta_description, d.keywords,
  now(), d.sections
from payload d
where d.slug not in (select slug from updated);
